import subprocess, re, sys, os
os.chdir('/tmp/mirror')
def git(*args, stdin=None, env=None):
    r = subprocess.run(['git', *args], input=stdin, capture_output=True, env=env)
    if r.returncode != 0:
        sys.exit(f"git {args} failed: {r.stderr.decode()}")
    return r.stdout
def sha(s): return s.decode().strip()

