def parents(c):
    return sha(git('rev-list','--parents','-n1',c)).split()[1:]

def btree(c):
    for p in ('packages/billing','services/billing'):
        r = subprocess.run(['git','rev-parse','-q','--verify',f'{c}:{p}'],capture_output=True)
        if r.returncode == 0:
            return sha(r.stdout)
    return EMPTY

def kept_parents(c, memo={}):
    out=[]
    for p in parents(c):
        if p in Kset:
            out.append(p)
        else:
            out.extend(x for x in kept_parents_of_nonkept(p))
    seen=[]; 
    for x in out:
        if x not in seen: seen.append(x)
    return seen

def kept_parents_of_nonkept(p):
    res=[]
    for q in parents(p):
        if q in Kset: res.append(q)
        else: res.extend(kept_parents_of_nonkept(q))
    return res

def parse_ident(line):
    m = re.match(rb'^(author|committer) (.*) <(.*?)> (\d+) ([+-]\d{4})$', line)
    assert m, line
    return m.group(2), m.group(3), m.group(4), m.group(5)

